#pragma once

#include <cstddef>
#include <cstdint>

#include "opentrail/secure_random.hpp"

namespace opentrail::target::heltec_v4_bench {

// Thin ESP-IDF adapter for the shared secure-random contract. The caller owns
// the entropy-readiness decision; this adapter retains no generated bytes and
// emits no diagnostics. Bounded sampling belongs to the consuming component.
class HeltecV4SecureRandom final : public security::SecureRandomSource {
public:
    void set_entropy_state(security::EntropyState state);

    [[nodiscard]] security::EntropyState state() const override;
    [[nodiscard]] security::RandomFillResult fill(
        std::uint8_t* output,
        std::size_t output_size) override;

private:
    security::EntropyState state_{security::EntropyState::not_ready};
};

}  // namespace opentrail::target::heltec_v4_bench
